  if f is None:break
  module=f.f_globals.get('__name__','')
  if module.startswith('pa.') and module not in ('pa.core.operation_budget','pa.core.async_runtime'):
   name=f.f_code.co_name
   if name=='wrapped':
    method=f.f_locals.get('method')
    if getattr(method,'__module__','').startswith('pa.'):
     name=getattr(method,'__name__',name)
   value=module+'.'+name
   if not out or value!=out[-1]:out.append(value)
  f=f.f_back
