   self.lock_id=locks.setdefault(self.lock,len(locks)+1);self.thread=threads.setdefault(tid,len(threads)+1)
   key=(self.lock_id,self.thread);self.depth=depths.get(key,0);depths[key]=self.depth+1
  return value
