  global next_operation
  assert re.fullmatch(r'[a-zA-Z0-9_.-]{1,100}',operation),'Only fixed source operation labels'
  with guard:next_operation+=1;invocation=next_operation
  def bound(*a,**kw):
   token=label.set((operation,invocation))
   try:return call(*a,**kw)
   finally:label.reset(token)
  return await original_run(self,operation,bound,*args,**kwargs)
